import crypto from 'node:crypto';
import { badRequest } from './errors.js';
import {
  AUDIO_EXTENSIONS,
  AUDIO_TYPES,
  MAX_AUDIO_BYTES,
  audioSizeProblem,
  audioTypeProblem,
  transcriptProblem,
} from '../../../shared/evaluation.js';

export { AUDIO_TYPES, MAX_AUDIO_BYTES, audioSizeProblem, audioTypeProblem };
export const CRITERIA = ['overall', 'clarity', 'naturalness'];

export const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
// Storage paths are generated by the server; anything else is not ours to register.
export const AUDIO_PATH = new RegExp(`^samples/[0-9a-f-]{36}\\.(${AUDIO_EXTENSIONS.join('|')})$`);

const text = (value) => String(value ?? '').trim();

// The same address always maps to the same hash, so the database can enforce one
// response per IP and clip without ever holding the address itself.
export function hashIp(ip, secret) {
  const address = text(ip).replace(/^::ffff:/, '').toLowerCase() || 'unknown';
  return crypto.createHmac('sha256', secret).update(`voicelk-evaluation:${address}`).digest('hex');
}

export function parseUploadRequest(body) {
  const filename = text(body?.filename).slice(0, 200);
  const contentType = text(body?.contentType).toLowerCase();
  const size = Number(body?.size);
  if (!filename) throw badRequest('Choose an audio file to upload.');
  const typeProblem = audioTypeProblem(contentType);
  if (typeProblem) throw badRequest(typeProblem, { audio: typeProblem });
  // The browser's declared size; the stored object is measured again before the clip is saved.
  const sizeProblem = Number.isInteger(size) ? audioSizeProblem(size) : 'That audio file is empty.';
  if (sizeProblem) throw badRequest(sizeProblem, { audio: sizeProblem });
  return { filename, contentType, size, extension: AUDIO_TYPES[contentType] };
}

export function parseSampleInput(body, { partial = false } = {}) {
  const value = {};
  const details = {};
  const has = (key) => !partial || body?.[key] !== undefined;

  if (has('title')) {
    value.title = text(body?.title);
    if (!value.title) details.title = 'Give the clip a title.';
    else if (value.title.length > 200) details.title = 'Keep the title under 200 characters.';
  }
  if (has('transcript')) {
    value.transcript = String(body?.transcript ?? '').replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n').trim();
    const problem = transcriptProblem(value.transcript);
    if (problem) details.transcript = problem;
  }
  if (has('system')) {
    value.system = text(body?.system);
    if (value.system.length > 120) details.system = 'Keep the model label under 120 characters.';
  }
  if (!partial || body?.transcriptFilename !== undefined) value.transcript_filename = text(body?.transcriptFilename).slice(0, 200);
  if (partial && body?.active !== undefined) value.active = Boolean(body.active);

  if (Object.keys(details).length) throw badRequest('Please check the form.', details);
  return value;
}

function rating(value) {
  const n = Number(value);
  return Number.isInteger(n) && n >= 1 && n <= 5 ? n : null;
}

export function parseFeedback(body) {
  const details = {};
  const scores = {};
  const labels = { overall: 'overall quality', clarity: 'clarity', naturalness: 'naturalness' };
  for (const key of CRITERIA) {
    scores[key] = rating(body?.[key]);
    if (scores[key] === null) details[key] = `Rate the ${labels[key]} from 1 to 5.`;
  }
  const verdict = text(body?.verdict).toLowerCase();
  if (!['pass', 'fail'].includes(verdict)) details.verdict = 'Choose pass or fail.';
  const comment = text(body?.comment);
  if (comment.length > 2000) details.comment = 'Keep your feedback under 2,000 characters.';

  if (Object.keys(details).length) throw badRequest('Please complete every rating.', details);
  return { ...scores, passed: verdict === 'pass', comment };
}

// Two-sided 95% Student-t critical values for 1–30 degrees of freedom; beyond
// that the normal approximation is close enough.
const T95 = [12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.16, 2.145,
  2.131, 2.12, 2.11, 2.101, 2.093, 2.086, 2.08, 2.074, 2.069, 2.064, 2.06, 2.056, 2.052, 2.048, 2.045, 2.042];

function describe(values) {
  const n = values.length;
  const distribution = [0, 0, 0, 0, 0];
  for (const v of values) distribution[v - 1] += 1;
  if (!n) return { mean: null, sd: null, ci95: null, distribution };
  const mean = values.reduce((sum, v) => sum + v, 0) / n;
  if (n < 2) return { mean, sd: null, ci95: null, distribution };
  const sd = Math.sqrt(values.reduce((sum, v) => sum + (v - mean) ** 2, 0) / (n - 1));
  return { mean, sd, ci95: (T95[n - 2] ?? 1.96) * (sd / Math.sqrt(n)), distribution };
}

// Mean opinion scores with 95% confidence intervals, the rating spread and the
// pass rate for a set of feedback rows.
export function summarize(rows) {
  const count = rows.length;
  const passed = rows.filter((r) => r.passed).length;
  return {
    count,
    passed,
    failed: count - passed,
    passRate: count ? passed / count : null,
    criteria: Object.fromEntries(CRITERIA.map((key) => [key, describe(rows.map((r) => r[key]))])),
  };
}
